 Button ModeButton(string label,string command,int icon){var b=Button("",command);b.Size=new Size(68,46);b.Paint+=delegate(object sender,PaintEventArgs e){var g=e.Graphics;using(var pen=new Pen(Color.Gainsboro,1.5f)){if(icon==0){pen.DashStyle=System.Drawing.Drawing2D.DashStyle.Dash;g.DrawRectangle(pen,24,5,19,17);}else if(icon==1){g.DrawLine(pen,34,4,34,23);g.DrawLine(pen,24,14,44,14);g.DrawLines(pen,new[]{new Point(30,8),new Point(34,4),new Point(38,8)});g.DrawLines(pen,new[]{new Point(40,10),new Point(44,14),new Point(40,18)});}else{g.DrawArc(pen,26,10,16,13,0,180);g.DrawLines(pen,new[]{new Point(26,17),new Point(23,11),new Point(26,10),new Point(29,14),new Point(29,5),new Point(32,5),new Point(32,12),new Point(35,7),new Point(38,9),new Point(41,10),new Point(42,17)});}}using(var labelFont=new Font(Font.FontFamily,7.5f))TextRenderer.DrawText(g,label,labelFont,new Rectangle(0,27,68,17),Color.Gainsboro,TextFormatFlags.HorizontalCenter);};return b;}
