 NumericUpDown Number(Control parent,string label,decimal value,decimal min,decimal max,int y){parent.Controls.Add(new Label{Text=label,Left=7,Top=y+4,Width=116,ForeColor=Color.Gainsboro});var n=new NumericUpDown{Left=127,Top=y,Width=76,DecimalPlaces=1,Minimum=min,Maximum=max,Value=value,BackColor=Color.FromArgb(32,36,40),ForeColor=Color.White};parent.Controls.Add(n);return n;}
