 ComboBox Combo(Control parent,string[] items,int x,int y,int width){var c=new DarkComboBox{Left=x,Top=y,Width=width,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Color.FromArgb(32,36,40),ForeColor=Color.White,FlatStyle=FlatStyle.Flat,DrawMode=DrawMode.OwnerDrawFixed};c.DrawItem+=delegate(object sender,DrawItemEventArgs e){using(var brush=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(50,70,86):Color.FromArgb(32,36,40)))e.Graphics.FillRectangle(brush,e.Bounds);int index=e.Index<0?c.SelectedIndex:e.Index;if(index>=0)TextRenderer.DrawText(e.Graphics,c.Items[index].ToString(),c.Font,e.Bounds,Color.White,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);};c.Items.AddRange(items);if(items.Length>0)c.SelectedIndex=0;parent.Controls.Add(c);return c;}
