 public TextStyle Style{get{return new TextStyle{Family=family.Text,Size=(float)size.Value,Bold=bold.Checked,Italic=italic.Checked,LineHeight=(float)line.Value,ParagraphGap=(float)paragraph.Value,CharacterSpacing=(float)character.Value,Ink=textColor,Alignment=textAlign.SelectedIndex,BoxWidth=boxWidth,Underline=underline.Checked,Strike=strike.Checked,Highlight=markColor,ListKind=listMode.SelectedIndex};}}
 public void ChooseColour(){using(var d=new ColorDialog{Color=textColor??Color.Black,FullOpen=true})if(d.ShowDialog(this)==DialogResult.OK){textColor=d.Color;ink.ForeColor=d.Color.GetBrightness()<.25f?Color.Silver:d.Color;Send("stylepreview");}}
 public void SetStyle(TextStyle style){loading=true;family.SelectedItem=style.Family;size.Value=(decimal)Math.Max(1,Math.Min(500,style.Size));bold.Checked=style.Bold;italic.Checked=style.Italic;line.Value=(decimal)style.LineHeight;paragraph.Value=(decimal)style.ParagraphGap;character.Value=(decimal)style.CharacterSpacing;textColor=style.Ink;boxWidth=style.BoxWidth;textAlign.SelectedIndex=style.Alignment;underline.Checked=style.Underline;strike.Checked=style.Strike;markColor=style.Highlight;listMode.SelectedIndex=style.ListKind;loading=false;}
